# Key: T!E -> Result[T, E]; x!E -> propagate(x, E); '# mut' marks a mutable
# binding; _fnN/_ifN/_mtN are a closure, if or mt lifted out of an expression;
# fixed-width types other than i64/f64 keep their toke names (i32, u8, f32).

# module bookmarks.api
import bookmarks.model as md
import std.http as http
import std.json as json
import std.str as str

store = bookmarks(items=[], nextid=1)  # mut


def tagstojson(tags: list[str]) -> str:
    buf = str.buf()
    str.add(buf, "[")
    i = 0
    while i < int(tags.len):
        if i > 0:
            str.add(buf, ",")
        str.add(buf, "\"")
        str.add(buf, tags[i])
        str.add(buf, "\"")
        i = i + 1
    str.add(buf, "]")
    return str.done(buf)


def bookmarktojson(b: bookmark) -> str:
    buf = str.buf()
    str.add(buf, "{\"id\":")
    str.add(buf, str.fromint(int(b.id)))
    str.add(buf, ",\"url\":\"")
    str.add(buf, b.url)
    str.add(buf, "\",\"title\":\"")
    str.add(buf, b.title)
    str.add(buf, "\",\"tags\":")
    str.add(buf, tagstojson(b.tags))
    str.add(buf, "}")
    return str.done(buf)


def bookmarkstojson(items: list[bookmark]) -> str:
    buf = str.buf()
    str.add(buf, "[")
    i = 0
    while i < int(items.len):
        if i > 0:
            str.add(buf, ",")
        str.add(buf, bookmarktojson(items[i]))
        i = i + 1
    str.add(buf, "]")
    return str.done(buf)


def findindex(id: u64) -> int:
    i = 0
    while i < int(store.items.len):
        b = store.items[i]
        if b.id == id:
            return i
        i = i + 1
    return 0 - 1


def handlelist(req: int) -> int:
    return http.resjson(200, bookmarkstojson(store.items))


def handleget(req: int) -> int:
    match str.toint(http.param(req, "id")):
        case ok(v):
            id = v
        case err(e):
            id = 0 - 1
    idx = findindex(u64(id))
    if idx < 0:
        return http.resjson(404, "{\"error\":\"not found\"}")
    return http.resjson(200, bookmarktojson(store.items[idx]))


def handlecreate(req: int) -> int:
    body = http.reqbody(req)
    match json.dec(body):
        case ok(d):
            doc = d
        case err(e):
            return http.resjson(400, "{\"error\":\"invalid json\"}")
    match json.str(doc, "url"):
        case ok(v):
            url = v
        case err(e):
            url = ""
    match json.str(doc, "title"):
        case ok(v):
            title = v
        case err(e):
            title = ""
    if str.len(url) == 0:
        return http.resjson(400, "{\"error\":\"missing url\"}")
    newb = bookmark(id=store.nextid, url=url, title=title, tags=[])
    store = bookmarks(items=store.items.push(newb), nextid=store.nextid + 1)
    return http.resjson(201, bookmarktojson(newb))


def handledelete(req: int) -> int:
    match str.toint(http.param(req, "id")):
        case ok(v):
            id = v
        case err(e):
            id = 0 - 1
    idx = findindex(u64(id))
    if idx < 0:
        return http.resjson(404, "{\"error\":\"not found\"}")
    kept = []  # mut
    i = 0
    while i < int(store.items.len):
        if (i == idx) == False:
            kept = kept.push(store.items[i])
        i = i + 1
    store = bookmarks(items=kept, nextid=store.nextid)
    return http.resjson(200, "{\"deleted\":true}")


def routes() -> int:
    http.get("/api/bookmarks", handlelist)
    http.post("/api/bookmarks", handlecreate)
    http.get("/api/bookmarks/:id", handleget)
    http.delete("/api/bookmarks/:id", handledelete)
    return 0
